  if (existing && existing.name !== 'air' && existing.name !== 'cave_air') {
    if (await nearTo(target)) { try { await bot.dig(existing, true) } catch (e) {} }
  }
  for (const face of FACES) {
    const ref = bot.blockAt(target.minus(face))
    if (!ref || ref.boundingBox !== 'block') continue
    if (!(await nearTo(target))) return 'out of reach'
    await bot.lookAt(target.offset(0.5, 0.5, 0.5), true)
    try { await bot.placeBlock(ref, face) } catch (e) { continue }
    const now = bot.blockAt(target)
    if (now && now.boundingBox === 'block') return 'placed'
  }
  return 'no face'
}

