async function moveTo(dest, maxIter = 300) {
  for (let i = 0; i < maxIter; i++) {
    const cur = bot.entity.position
    const d = cur.distanceTo(dest)
    if (d < 0.5) return true
    const dir = dest.minus(cur)
    const s = Math.min(0.7, d) / d
    const np = cur.plus(dir.scaled(s))
    bot.entity.position.set(np.x, np.y, np.z)
    bot._client.write('position', { x: np.x, y: np.y, z: np.z, onGround: false })
    await sleep(50)
  }
  return bot.entity.position.distanceTo(dest) < 1.0
}

